ee:variables.ee:set-variable:
%dw 2.0
output application/json
var records = vars.extractedRecords default []
var agg = vars.aggregateTotals[0] default {}

var extractedCount = sizeOf(records)
var aggCount = (agg.total_records default 0) as Number

var extractedAmount = sum(records map ((r) -> (r.amount default 0.00) as Number)) default 0.00
var aggAmount = (agg.total_amount default 0.00) as Number

var extractedCustomers = sizeOf(records distinctBy ((r) -> r.customer_id default r.customerId))
var aggCustomers = (agg.total_customers default 0) as Number

var countMatches = (extractedCount == aggCount)
var amountMatches = (abs(extractedAmount - aggAmount) < 0.009)
var customerMatches = (extractedCustomers == aggCustomers)

var isMatch = countMatches and amountMatches and customerMatches
---
{
	isMatch: isMatch,
	result: if (isMatch) "PASS" else "FAIL",
	extractedCount: extractedCount,
	aggCount: aggCount,
	extractedAmount: extractedAmount,
	aggAmount: aggAmount,
	extractedCustomers: extractedCustomers,
	aggCustomers: aggCustomers,
	discrepancies: {
		countMatch: countMatches,
		amountMatch: amountMatches,
		customerMatch: customerMatches
	}
}

%dw 2.0
output text/plain
fun sanitize(val: Any) = 
  if (val == null) "" 
  else (val as String replace "|" with "-" replace "\n" with " " replace "\r" with "")

var entityCode = sanitize(vars.runContext.entityCode)
var entityName = sanitize(vars.runContext.entityName)
var reportType = sanitize(vars.runContext.reportType)
var periodDate = (vars.runContext.periodEnd[0 to 9]) default (now() as String {format: "yyyy-MM-dd"})
var generatedAt = (vars.runContext.generatedAt as String) default (now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"})
var sequenceNumber = (vars.runContext.sequenceNumber as Number) as String {format: "000"}
var currency = sanitize(vars.runContext.currency default "USD")
---
["H", entityCode, entityName, reportType, periodDate, generatedAt, sequenceNumber, currency] joinBy "|"

%dw 2.0
import dw::Crypto
import dw::core::Binaries
output application/json

var records = vars.extractedRecords default []
var recordCount = sizeOf(records)

var totalAmount =
    sum(
        records map ((r) ->
            (r.amount default 0.00) as Number
        )
    ) default 0.00

var customerCount =
    sizeOf(
        records distinctBy ((r) ->
            r.customer_id default r.customerId
        )
    )

// Calculate the SHA-256 checksum.
var checksum =
    if (recordCount == 0)
        "NIL_REPORT"
    else
        upper(
            Binaries::toHex(
                Crypto::hashWith(
                    (vars.detailSection as String) as Binary,
                    "SHA-256"
                )
            )
        )

---
{
    recordCount: recordCount,
    totalAmount: totalAmount,
    customerCount: customerCount,
    completenessResult: "PASS",
    checksum: checksum,
    isNilReport: recordCount == 0
}
